import sys
from collections import Counter

def main():
    input = sys.stdin.read().split()
    index = 1
    results = []
    for _ in range(int(input[0])):
        N = int(input[index])
        if N == 1:
            results.append("1")
        elif N == 2:
            results.append("1 2")
        else:
            arr = []
            for i in range(N):
                arr.append(i % 3 + 1)
            results.append(" ".join(map(str, arr)))
        index += 1
    print("\n".join(results))

main()
